"тихо"], ["не шум"]]}, {"ua": "з 22:00 до 7:00", "keys": [["22", "7"], ["десят", "сьом"]]}], "hints": [], "models": ["Просять тиші з 22:00 до 7:00."]}}, {"id": "7cc80fff-31df-5b4d-a145-92ca8e1bc143", "lesson": "3365f423-e694-5b55-baa1-3205fba11aff", "type": "write_message", "level": "A1", "skill": "writing", "question": "Вам треба перенести зустріч із колегою. Напишіть йому: вибачтеся, скажіть, що в середу не можете, і запропонуйте четвер.", "answer": "Oprosti, u srijedu ne mogu doći na sastanak. Možemo li ga pomaknuti na četvrtak?", "task": {"situation_ua": "Вам треба перенести зустріч із колегою. Напишіть йому: вибачтеся, скажіть, що в середу не можете, і запропонуйте четвер.", "points": [{"ua": "вибачтеся", "keys": [["isprič"], ["oprost"], ["žao mi"]]}, {"ua": "у середу не можете", "keys": [["srijed", "ne mog"], ["srijed", "ne="]]}, {"ua": "запропонуйте четвер", "keys": [["četvrt"]]}], "hints": ["sastanak", "u srijedu", "ne mogu", "pomaknuti", "na četvrtak"], "models": ["Oprosti, u srijedu ne mogu doći na sastanak. Možemo li ga pomaknuti na četvrtak?"]}}, {"id": "5ba3e778-875b-583e-83b3-91ba7d101ef3", "lesson": "3365f423-e694-5b55-baa1-3205fba11aff", "type": "mediation", "level": "A1", "skill": "mediation", "question": "Друг не знає хорватської. Перекажіть йому українською головне.", "answer": "Зустріч перенесли на наступний тиждень — у вівторок о 9:00.", "task": {"situation_ua": "Друг не знає хорватської. Перекажіть йому українською головне.", "source_hr": "Sastanak je odgođen za sljedeći tjedan.\nNovi termin: utorak u 9 sati.", "friend_ua": "Що пишуть про зустріч?", "direction": "hr_ua", "points": [{"ua": "перенесли на наступний тиждень", "keys": [["наступн"]]}, {"ua": "у вівторок о 9:00", "keys": [["вівтор", "9"], ["вівтор", "дев''ят"]]}], "hints": [], "models": ["Зустріч перенесли на наступний тиждень — у вівторок о 9:00."]}}, {"id": "dd7d3433-e978-5d2e-ac75-567c26dc4c0d", "lesson": "ad0bc1f4-2808-5b24-969d-9da64d4a7a4d", "type": "write_message", "level": "A1", "skill": "writing", "question": "Подруга питає, чи ви вже знайшли роботу. Напишіть: ще ні, але саме зараз шукаєте, і в п’ятницю навіть маєте співбесіду.", "answer": "Još ne, ali upravo tražim posao. U petak čak imam razgovor za posao!", "task": {"situation_ua": "Подруга питає, чи ви вже знайшли роботу. Напишіть: ще ні, але саме зараз шукаєте, і в п’ятницю навіть маєте співбесіду.", "points": [{"ua": "ще ні", "keys": [["još ne"], ["još nis"], ["još uvijek ne"]]}, {"ua": "саме зараз шукаєте", "keys": [["traž"]]}, {"ua": "співбесіда в п’ятницю", "keys": [["petak"], ["petk"]]}], "hints": ["još ne", "upravo", "tražim posao", "čak", "razgovor za posao", "u petak"], "models": ["Još ne, ali upravo tražim posao. U petak čak imam razgovor za posao!"]}}, {"id": "c9db7dd1-ee0c-5235-b098-8a9d09daa7fa", "lesson": "ad0bc1f4-2808-5b24-969d-9da64d4a7a4d", "type": "mediation", "level": "A1", "skill": "mediation", "question": "Друг не знає хорватської. Перекажіть йому українською головне.", "answer": "Пише, що знову запізнюється: автобуса ще немає, буде за 15 хвилин.", "task": {"situation_ua": "Друг не знає хорватської. Перекажіть йому українською головне.", "source_hr": "Opet kasnim, oprosti!\nAutobus još ne dolazi. Stižem za 15 minuta.", "friend_ua": "Що вона пише? Коли буде?", "direction": "hr_ua", "points": [{"ua": "знову запізнюється", "keys": [["запізн"]]}, {"ua": "автобуса ще немає", "keys": [["автобус"]]}, {"ua": "буде за 15 хвилин", "keys": [["15"], ["п''ятнадцят"]]}], "hints": [], "models": ["Пише, що знову запізнюється: автобуса ще немає, буде за 15 хвилин."]}}]'::jsonb)
      as t(id uuid, lesson uuid, type text, level text, skill text, question text, answer text, task jsonb)
  loop
    insert into public.exercises (id, exercise_type, question_text, correct_answer, options, level, order_index, status, task)
    values (r.id, r.type, r.question, r.answer, null, r.level, 0, 'PUBLISHED', r.task)
    on conflict (id) do nothing;
    if found then
      v_ex := v_ex + 1;
      insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
      values ('exercise', r.id, null, 'PUBLISHED', 'auto_passed', 'ai', '[]'::jsonb, 'writing_pilot 2026-11-05: «Напишіть повідомлення» і «Перекажіть другу» (§57, §58), модулі A0.1 і A1.1. Бета (рішення власника), потрібна перевірка носієм.');
    end if;
    if not exists (select 1 from public.lesson_items where lesson_id = r.lesson and item_type = 'exercise' and item_id = r.id) then
      select coalesce(max(order_index), 0) + 1 into v_ord from public.lesson_items where lesson_id = r.lesson;
      insert into public.lesson_items (id, lesson_id, item_type, item_id, order_index, required, target_skill)
      values (gen_random_uuid(), r.lesson, 'exercise', r.id, v_ord, false, r.skill);
      v_items := v_items + 1;
    end if;
  end loop;

  -- Самоперевірка: у кожному уроці пілоту — по одній вправі кожного типу з коректним завданням
  if (select count(*) from public.lesson_items li join public.exercises e on e.id = li.item_id
       where li.item_type = 'exercise' and li.lesson_id in ('c0000000-0000-0000-0000-000000000001'::uuid, 'd8cffb46-8a62-538a-b864-e227a6d8b863'::uuid, 'a17f2f16-1be9-50f2-8e16-2bebfcced33b'::uuid, 'e704760a-f743-5762-9c1a-027b10ca030a'::uuid, '4bf48151-be83-5108-bc92-645c0603a1a3'::uuid, '54f17cf7-3c17-5978-b400-b6b6888c9f84'::uuid, '959e879f-a28d-5bed-9c09-16cff91ef456'::uuid, '9c38f909-9275-5194-9a6e-f799c6e416ce'::uuid, 'd43d6c65-1ce3-5c72-9ecd-cce2ed200fc2'::uuid, '1968c7d5-4e3a-5b1e-92f6-88df711e9c54'::uuid, '458b73de-d6b3-5bd3-98ad-c243a2fff03f'::uuid, '63a4a6d8-1cae-5e0e-90ff-98efcfe8b4c7'::uuid, '3365f423-e694-5b55-baa1-3205fba11aff'::uuid, 'ad0bc1f4-2808-5b24-969d-9da64d4a7a4d'::uuid) and e.status = 'PUBLISHED'
         and e.exercise_type in ('write_message', 'mediation') and jsonb_array_length(e.task -> 'points') between 1 and 5) <> 28 then
    raise exception 'Не всі вправи пілоту на місцях';
  end if;
  raise notice 'Готово: вправ створено %, додано в уроки % (усього в пілоті 28)', v_ex, v_items;
end
